class FairishLock {
    private final Deque<Thread> kolejka = new ArrayDeque<>();
    private boolean zajety = false;
    synchronized void lock() throws InterruptedException {
        Thread ja = Thread.currentThread();
        kolejka.addLast(ja);
        while (zajety || kolejka.peekFirst() != ja) wait();
        kolejka.removeFirst();
        zajety = true;
    }
    synchronized void unlock() { zajety = false; notifyAll(); }
}
