static double coefficientOfVariation(int[] wartosci) {
    double srednia = Arrays.stream(wartosci).average().getAsDouble();
    double wariancja = Arrays.stream(wartosci).mapToDouble(v -> Math.pow(v-srednia,2)).average().getAsDouble();
    return Math.sqrt(wariancja) / srednia;
}
